input.new_string:
// ============================================================================
// board_cradle: holds the Waveshare ESP32-S3-Touch-LCD-3.5-C so the SCREEN
// faces UP (owner reads it) and the CAMERA (dead-centre of the back) looks
// straight DOWN through a window at the bowl.
//
// The board rests SCREEN-UP on four posts and is fixed with four M2.5 screws
// dropped through the corner mounting holes from the top. The camera peers down
// through CAM_WIN in the base; the bottom GPIO header clears through HDR_SLOT,
// and that slot is also where the servo signal wire reaches GPIO43.
//
// Dimensions are from the Waveshare -C outline drawing (mm):
//   board 95.11 x 63.67 x 14.1, corner R7.30
//   4 holes 72.00 apart (X) x 48.50 apart (Y)  -> +/-36.00, +/-24.25 from centre
//   camera: centre of the board
// VERIFY BEFORE PRINTING: the mounting-hole diameter and the camera-lens barrel
// diameter are NOT on the drawing -- these two are assumed (see marked values).
// ============================================================================
BM_W        = 95.11;   // board width
BM_H        = 63.67;   // board height
BM_CORNER   = 7.30;    // board corner radius
BM_HOLE_X   = 36.00;   // mounting hole offset from centre, X (72.00 / 2)
BM_HOLE_Y   = 24.25;   // mounting hole offset from centre, Y (48.50 / 2)
BM_SCREW_D  = 2.2;     // M2.5 self-tap pilot in the posts  <-- assumed, verify
BM_POST_R   = 4;       // post outer radius
BM_STANDOFF = 12;      // board sits this high -> clears camera barrel + header
BM_BASE_T   = 3;       // base plate thickness
BM_WALL     = 2.4;     // locating wall around the board
BM_WALL_H   = 5;       // locating wall height
BM_CAM_WIN  = 14;      // camera window dia (centre)  <-- assumed lens barrel, verify
BM_HDR_W    = 40;      // GPIO header slot width  (2x14 @2.54 ~ 36mm + margin)
BM_HDR_D    = 8;       // GPIO header slot depth
BM_HDR_OFF  = 22;      // header slot centre, from board centre toward -Y (bottom)

module board_cradle() {
    difference() {
        union() {
            // base plate (rounded like the board)
            linear_extrude(BM_BASE_T)
                offset(r = BM_CORNER) offset(r = -BM_CORNER)
                    square([BM_W + 2*BM_WALL, BM_H + 2*BM_WALL], center = true);
            // four locating walls (short, just to seat the board squarely)
            for (sx = [-1, 1])
                translate([sx * (BM_W/2 + BM_WALL/2), 0, 0])
                    translate([-BM_WALL/2, -BM_H/2, 0])
                        cube([BM_WALL, BM_H, BM_BASE_T + BM_WALL_H]);
            for (sy = [-1, 1])
                translate([0, sy * (BM_H/2 + BM_WALL/2), 0])
                    translate([-BM_W/2, -BM_WALL/2, 0])
                        cube([BM_W, BM_WALL, BM_BASE_T + BM_WALL_H]);
            // four screw posts at the mounting holes
            for (sx = [-1, 1], sy = [-1, 1])
                translate([sx * BM_HOLE_X, sy * BM_HOLE_Y, 0])
                    cylinder(r = BM_POST_R, h = BM_BASE_T + BM_STANDOFF);
        }
        // pilot holes down the posts
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * BM_HOLE_X, sy * BM_HOLE_Y, BM_BASE_T])
                cylinder(d = BM_SCREW_D, h = BM_STANDOFF + 0.1);
        // camera window, centre
        translate([0, 0, -0.1]) cylinder(d = BM_CAM_WIN, h = BM_BASE_T + 0.2);
        // GPIO header slot (also the servo-wire exit)
        translate([-BM_HDR_W/2, -BM_HDR_OFF - BM_HDR_D/2, -0.1])
            cube([BM_HDR_W, BM_HDR_D, BM_BASE_T + 0.2]);
    }
}

if      (part == "rotor")        rotor();
else if (part == "housing")      housing();
else if (part == "plate_servo")  plate_servo();
else if (part == "plate_idle")   plate_idle();
else if (part == "hopper")       hopper();
else if (part == "board_cradle") board_cradle();
else                             assembly();

