// ============================================================================
// product: CONCEPT preview of the whole appliance (do NOT print). Feeder +
// a bowl under the outlet + the board cradle up on a post, screen to the owner,
// camera angled down at the bowl / approach. Placements are illustrative.
// ============================================================================
module bowl() {
    translate([0, 0, -62])
        difference() {
            cylinder(r1 = 24, r2 = 46, h = 24);
            translate([0, 0, 3]) cylinder(r1 = 21, r2 = 45, h = 24);
        }
}
module product() {
    assembly();                                   // feeder (hopper/drum/rotor/plates)
    color("BurlyWood") bowl();                    // bowl under the outlet
    // support post rising beside the feeder
    color("DarkSlateGray")
        translate([-46, 60, -60]) cube([10, 10, 175]);
    // board cradle up high on the post, rotated to face the owner while its
    // (tilted) camera looks back-and-down toward the bowl
    color("DimGray")
        translate([0, 78, 112]) rotate([0, 0, 180]) board_cradle_stand();
}

if      (part == "rotor")        rotor();

else if (part == "board_cradle_stand") board_cradle_stand();
else if (part == "product")      product();
else                             assembly();

