/* ---- FEEDER SERVO on GPIO43 (LEDC channel 1 / timer 1, 50 Hz) -------------
 * The camera's XCLK already uses LEDC ch0/timer0 at 20 MHz, so the servo takes
 * ch1/timer1. Hobby servo: 20 ms period, ~1.0 ms pulse = closed, ~2.0 ms = open.
 * timer1: 80 MHz / 97.65625 / 2^14 = 50 Hz  (period = 16384 duty counts).
 *   clk_div fixed point = int 97 (<<12) | frac 168 (<<4)  -> 97.65625
 */
#define SERVO_PIN            43
#define R_LEDC_CH1_CONF0     (LEDC_BASE + 0x14)
#define R_LEDC_CH1_HPOINT    (LEDC_BASE + 0x18)
#define R_LEDC_CH1_DUTY      (LEDC_BASE + 0x1c)
#define R_LEDC_CH1_CONF1     (LEDC_BASE + 0x20)
#define R_LEDC_TIMER1_CONF   (LEDC_BASE + 0xa8)
#define SERVO_DUTY_BITS      14
#define SERVO_PERIOD_CNT     16384          /* 2^14, = 20 ms */

/* PADDLE-ROTOR metering (hardware/velapaw_feeder.scad).
 *
 * The rotor has ROTOR_POCKETS vanes running in a round housing under the
 * hopper. One pocket holds a FIXED VOLUME of kibble, so the portion depends on
 * how much the rotor turns -- NOT on how long a gate stays open, and NOT on how
 * full the hopper is. That is the entire reason for the rotor: a flap's dose
 * grows with hopper weight, which would quietly wreck the per-pet portion
 * control the product is built on.
 *
 * ---- WHY A FULL 180-DEGREE SWEEP, NOT A SMALL WOBBLE --------------------------
 * The inlet (top) and outlet (bottom) are 180 degrees apart, and the MG90S can
 * only oscillate (no continuous spin). A SHORT sweep + return has ZERO net
 * rotation, so a pocket filled at the inlet can never travel the 180 deg to the
 * outlet -- the machine would drop its initial charge a few times and then
 * DEAD-HEAD forever. (This was the original 60-deg bug.)
 *
 * The fix is a FULL 180-degree oscillation with a dwell at each end:
 *   HOME(0) --sweep--> 180 : the pocket under the inlet rides down to the outlet
 *                            and drops; the pocket that was at the outlet is now
 *                            under the inlet.
 *   dwell                  : that pocket fills from the hopper.
 *   180 --sweep--> HOME(0) : the just-filled pocket rides back to the outlet and
 *                            drops.
 * So ONE full cycle drops ~2 pockets, consistently cycle-to-cycle. Calibrate
 * GRAMS_PER_CYCLE (weigh one cycle's output).  grams = cycles x GRAMS_PER_CYCLE.
 * (Two side pockets never reach the outlet -- permanent dead storage; kibble
 *  parked there can go stale. Harmless, but empty the hopper for long idle.)
 *
 * 1000us = 0 deg, 2000us = 180 deg.
 */
#define ROTOR_POCKETS        6              /* vanes; must match the .scad */
#define SERVO_HOME_US        1000           /* rotor at 0 deg (rest)   */
#define SERVO_FULL_US        2000           /* rotor at 180 deg        */
#define SERVO_MOVE_MS        450            /* time for one 180 sweep  */
#define SERVO_DWELL_MS       350            /* fill/drop settle per end */
#define GRAMS_PER_CYCLE      9              /* CALIBRATE: weigh one full cycle */

static void servo_set_us(int us)
{
  uint32_t duty = (uint32_t)(((long)us * SERVO_PERIOD_CNT) / 20000);
  wreg(R_LEDC_CH1_DUTY, duty << 4);         /* duty has 4 fractional bits */
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_PARAUP);
}

void board_feeder_init(void)
{
  sreg(R_SYS_CLK_EN0, B_SYS_LEDC);
  creg(R_SYS_RST_EN0, B_SYS_LEDC);
  wreg(R_LEDC_CONF, 1);                     /* APB clock source */
  sreg(R_LEDC_CONF, B_LEDC_CLK_EN);

  sreg(R_LEDC_TIMER1_CONF, B_LEDC_T0_RST);
  wreg(R_LEDC_TIMER1_CONF,
       (SERVO_DUTY_BITS << S_LEDC_DUTYRES) |
       (168u << S_LEDC_CLKDIV) |            /* frac .65625 */
       (97u  << (S_LEDC_CLKDIV + 8)));      /* int  97     */
  sreg(R_LEDC_TIMER1_CONF, B_LEDC_T0_PARAUP);

  wreg(R_LEDC_CH1_CONF0, 1);                /* channel1 -> timer1 */
  wreg(R_LEDC_CH1_CONF1, 0);
  wreg(R_LEDC_CH1_HPOINT, 0);
  servo_set_us(SERVO_HOME_US);
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_SIGOUT);
  sreg(R_LEDC_CH1_CONF1, B_LEDC_CH0_DUTYST);
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_PARAUP);

  esp32s3_configgpio(SERVO_PIN, OUTPUT);
  esp32s3_gpio_matrix_out(SERVO_PIN, LEDC_SIG_OUT0_IDX + 1, 0, 0);
