}

/* One full 180-degree oscillation = ~2 pockets dropped. Dwell at each end so a
 * pocket has time to FILL under the inlet and DROP at the outlet (see the block
 * comment above for the kinematics -- a short sweep does not dispense). */
static void rotor_cycle(void)
{
  servo_set_us(SERVO_FULL_US);                 /* carry inlet pocket -> outlet */
  nxsig_usleep(SERVO_MOVE_MS * 1000);
  nxsig_usleep(SERVO_DWELL_MS * 1000);         /* new pocket fills at the inlet */
  servo_set_us(SERVO_HOME_US);                 /* carry it back -> outlet       */
  nxsig_usleep(SERVO_MOVE_MS * 1000);
  nxsig_usleep(SERVO_DWELL_MS * 1000);         /* drop settles                  */
}

/* Dispense `grams` by indexing whole pockets (rounded to nearest). MUST NOT run
 * on the UI thread (it sleeps ~0.8s per pocket): the app calls this from a
 * detached worker thread -- see hal/feeder_servo.c. */
int board_feeder_dispense(int grams)
{
  int cycles;
  int i;

  if (grams <= 0) return -1;

  /* round to the nearest whole cycle; always give at least one */
  cycles = (grams + GRAMS_PER_CYCLE / 2) / GRAMS_PER_CYCLE;
  if (cycles < 1) cycles = 1;

  for (i = 0; i < cycles; i++)
    {
      rotor_cycle();
    }

  syslog(LOG_ERR, "[feeder] dispensed %d cycle(s) ~%dg (asked %dg)\n",
