/* ---- FEEDER: 28BYJ-48 STEPPER via ULN2003 --------------------------------
 * Replaces the MG90S servo. A stepper gives CONTINUOUS one-direction rotation,
 * so pockets ratchet inlet->outlet and never reverse -> TRUE per-pocket
 * metering: grams = pockets x GRAMS_PER_POCKET, literally. (The servo could
 * only oscillate; with the inlet/outlet 180 deg apart that made honest per-
 * pocket dosing impossible -- see git history.)
 *
 * 28BYJ-48: 32 steps/motor-rev x ~63.68 gear, driven half-step (8-phase) =
 * ~4096 half-steps per OUTPUT revolution. 6 pockets -> 4096/6 ~= 682 half-steps
 * per pocket. Driven through a ULN2003 board: IN1..IN4 <- 4 GPIOs; the board
 * takes 5V (same separate supply as before) + GND common with the ESP32.
 *
 * Pins: the ES8311 audio codec's clock/data lines. VelaPaw uses no audio, and
 * these are all ESP32->codec directions (safe to drive; the codec is never
 * enabled). Chosen to stay off the LCD / camera / touch / SD / I2C / USB pins.
 * Change freely if you add audio.
 */
#define STEP_IN1             12       /* ES8311 MCLK  (unused audio) */
#define STEP_IN2             13       /* ES8311 SCLK  (unused audio) */
#define STEP_IN3             15       /* ES8311 LRCK  (unused audio) */
#define STEP_IN4             16       /* ES8311 DSDIN (unused audio) */
#define ROTOR_POCKETS        6                    /* vanes; must match the .scad */
#define STEP_PER_REV         4096                 /* 28BYJ-48 half-steps / rev   */
#define STEP_PER_POCKET      (STEP_PER_REV / ROTOR_POCKETS)   /* ~682 */
#define STEP_DELAY_US        1500     /* per half-step; 28BYJ-48 reliable ~1-2ms */
#define GRAMS_PER_POCKET     4        /* CALIBRATE: weigh one pocket (~4.3g est) */

/* 8-step half-step drive sequence; bits 3..0 = IN1..IN4 */
static const uint8_t k_halfstep[8] =
{
  0x8, 0xC, 0x4, 0x6, 0x2, 0x3, 0x1, 0x9
};

static void step_coils(uint8_t b)
{
  esp32s3_gpiowrite(STEP_IN1, (b >> 3) & 1);
  esp32s3_gpiowrite(STEP_IN2, (b >> 2) & 1);
  esp32s3_gpiowrite(STEP_IN3, (b >> 1) & 1);
  esp32s3_gpiowrite(STEP_IN4, (b >> 0) & 1);
}

void board_feeder_init(void)
{
  esp32s3_configgpio(STEP_IN1, OUTPUT);
  esp32s3_configgpio(STEP_IN2, OUTPUT);
  esp32s3_configgpio(STEP_IN3, OUTPUT);
  esp32s3_configgpio(STEP_IN4, OUTPUT);
  step_coils(0);                       /* coils off at rest: no heat, no hum */
  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready (ULN2003 on %d/%d/%d/%d)\n",
         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
}

/* Rotate the rotor FORWARD by n half-steps (ONE direction -> pockets ratchet
 * inlet->outlet). Busy-waits STEP_DELAY_US per step, so it MUST run off the UI
 * thread -- the app calls board_feeder_dispense from a detached worker (see
 * hal/feeder_servo.c). Coils de-energise at the end (no holding current/heat). */
static void rotor_step(int n)
{
  static int phase = 0;
  int i;

  for (i = 0; i < n; i++)
    {
      phase = (phase + 1) & 7;
      step_coils(k_halfstep[phase]);
      up_udelay(STEP_DELAY_US);
    }
  step_coils(0);
}

int board_feeder_dispense(int grams)
{
  int pockets;

  if (grams <= 0) return -1;

  /* round to the nearest whole pocket; always give at least one */
  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
  if (pockets < 1) pockets = 1;

  rotor_step(pockets * STEP_PER_POCKET);

  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (asked %dg)\n",
         pockets, pockets * GRAMS_PER_POCKET, grams);
  return 0;
}

