202	static long mono_ms(void)
203	{
204	  struct timespec ts;
205	  clock_gettime(CLOCK_MONOTONIC, &ts);
206	  return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
207	}
208	
209	/* ---- wall clock -----------------------------------------------------------
210	 * Software CLOCK_REALTIME (no hardware RTC: enabling it killed the USB console,
211	 * so the clock is set by the user each session via Set Clock and starts at a
212	 * sane default). LOCALTIME is off, so derive HH:MM straight from epoch seconds
213	 * and treat that as local time. */
214	static int wall_min(void)          /* minute-of-day, 0..1439 */
215	{
216	  struct timespec ts;
217	  clock_gettime(CLOCK_REALTIME, &ts);
218	  return (int)((ts.tv_sec % 86400) / 60);
219	}
220	static long wall_day(void)         /* day number (for per-day "fed" resets) */
221	{
222	  struct timespec ts;
223	  clock_gettime(CLOCK_REALTIME, &ts);
224	  return (long)(ts.tv_sec / 86400);
225	}
226	/* Board hook: persist the clock into the on-board PCF85063 RTC chip (direct
227	 * I2C in the board file). Weak-ish: returns <0 if the chip isn't there. */
228	extern int board_rtc_settime(time_t t);
229	
230	static void wall_set_min(int minofday)   /* set clock to today at HH:MM */
231	{
232	  struct timespec ts;
233	  clock_gettime(CLOCK_REALTIME, &ts);
234	  if (minofday < 0) minofday += 1440;
235	  minofday %= 1440;
236	  ts.tv_sec  = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
237	  ts.tv_nsec = 0;
238	  clock_settime(CLOCK_REALTIME, &ts);
239	  board_rtc_settime(ts.tv_sec);   /* survive reset / power-off */
240	}
