291	/****************************************************************************
292	 * frame display
293	 ****************************************************************************/
294	
295	static void frame_to_565(const struct velapaw_frame *f, uint16_t *dst)
296	{
297	  /* Rotate 90 deg counter-clockwise while converting (the sensor is mounted
298	   * rotated). Square frame (128x128), dims unchanged. dst(dr,dc)=src(dc, W-1-dr). */
299	  int W = f->width, H = f->height;
300	  for (int dr = 0; dr < H; dr++)
301	    for (int dc = 0; dc < W; dc++)
302	      {
303	        int si = (dc * W + (W - 1 - dr)) * 3;
304	        uint8_t r = f->data[si + 0];
305	        uint8_t g = f->data[si + 1];
306	        uint8_t b = f->data[si + 2];
307	        dst[dr * W + dc] = (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
308	      }
309	}
310	
311	/* Thumbnail version: same 90-deg CCW rotation, decimated 2x (128x128 -> 64x64). */
312	static void frame_to_thumb565(const struct velapaw_frame *f, uint16_t *dst)
313	{
314	  int W = f->width;                     /* 128 (square) */
315	  for (int dr = 0; dr < THUMB_H; dr++)
316	    for (int dc = 0; dc < THUMB_W; dc++)
317	      {
318	        int si = ((dc * 2) * W + (W - 1 - dr * 2)) * 3;
319	        uint8_t r = f->data[si + 0];
320	        uint8_t g = f->data[si + 1];
321	        uint8_t b = f->data[si + 2];
322	        dst[dr * THUMB_W + dc] =
323	            (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
324	      }
325	}
