340	/****************************************************************************
341	 * camera capture, counted
342	 *
343	 * The board wedged (console "semaphore timeout") after a long idle on the
344	 * Enroll tab -- the preview grabs a frame every FRAME_INTERVAL_MS forever, so
345	 * minutes of idling = many thousands of captures, and the next Capture died.
346	 * Every capture goes through here so the log tells us the frame number at the
347	 * wedge: a repeatable count => something leaks per-capture; no pattern => it's
348	 * time/temperature/electrical. Do not guess this one again.
349	 ****************************************************************************/
350	
351	static unsigned long g_cap_n;
352	
353	/* ---- background inference worker: shared state -----------------------------
354	 * Declared up here because BOTH the recognize loop and Enroll's Capture hand
355	 * work to the worker. Inference MUST NOT run on the UI task: that task's stack
356	 * is in PSRAM, and running the ESP-NN/TFLM Invoke on a PSRAM stack wedges the
357	 * SoC (console goes dead, "semaphore timeout") -- the same trap the flash model
358	 * loader hit. A pthread's stack is heap/internal RAM, where it runs fine.
359	 * Protocol: 0 idle -> 1 request -> 2 busy -> 3 done -> 0. */
360	static struct velapaw_frame   g_inf_frame;
361	static float                  g_inf_emb[VELAPAW_EMBED_DIM];
362	static struct velapaw_match   g_inf_m;
363	static uint32_t               g_inf_us;
364	static volatile int           g_inf_state;  /* 0 idle,1 request,2 busy,3 done */
365	static volatile int           g_inf_mode;   /* 0 = recognize, 1 = enroll capture */
366	static int                    g_cap_pending;/* an enroll capture is in flight */
367	
368	static void cam_grab(struct velapaw_frame *f)
369	{
370	  velapaw_camera_get_frame(f);
371	  if (++g_cap_n % 200 == 0)
372	    {
373	      printf("velapaw/cam: capture #%lu\n", g_cap_n);
374	    }
375	}
