377	/****************************************************************************
378	 * appetite / alert  (relative to each pet's DAILY LIMIT = the ration the
379	 * owner set, not a rolling average)
380	 ****************************************************************************/
381	
382	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
383	 * at the limit). 100% = ate its full daily allowance. */
384	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
385	{
386	  int today = velapaw_store_today_total(id);
387	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
388	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
389	}
390	
391	/* appetite-drop alert: the last completed day was under half the daily limit. */
392	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
393	{
394	  int yesterday = velapaw_store_day_total(id, 1);
395	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
396	}
