402	static void refresh_enroll(void)
403	{
404	  if (g_meal_lbl)
405	    {
406	      /* show all 3 meals; mark the one the +/- buttons are editing with [ ] */
407	      char buf[64]; int n = 0;
408	      n += snprintf(buf + n, sizeof(buf) - n, LV_SYMBOL_BELL " Meals:");
409	      for (int k = 0; k < VELAPAW_MAX_MEALS && n < (int)sizeof(buf) - 12; k++)
410	        {
411	          n += snprintf(buf + n, sizeof(buf) - n,
412	                        (k == g_meal_sel) ? " [%02d:%02d]" : " %02d:%02d",
413	                        g_meal_min[k] / 60, g_meal_min[k] % 60);
414	        }
415	      lv_label_set_text(g_meal_lbl, buf);
416	    }
417	  if (g_clock_lbl)
418	    {
419	      int c = wall_min();
420	      lv_label_set_text_fmt(g_clock_lbl, "Clock now: %02d:%02d  (set it)",
421	                            c / 60, c % 60);
422	    }
423	  lv_label_set_text_fmt(g_sample_lbl, "Sample %d of %d", g_nsamp, MAX_SHOTS);
424	  lv_bar_set_value(g_progress, g_nsamp * 100 / MAX_SHOTS, LV_ANIM_OFF);
425	  for (int i = 0; i < MAX_SHOTS; i++)
426	    {
427	      if (i < g_nsamp)
428	        {
429	          lv_obj_clear_flag(g_thumb[i], LV_OBJ_FLAG_HIDDEN);
430	        }
431	      else
432	        {
433	          lv_obj_add_flag(g_thumb[i], LV_OBJ_FLAG_HIDDEN);
434	        }
435	    }
436	}
