438	static void do_capture(void)
439	{
440	  if (g_nsamp >= MAX_SHOTS)
441	    {
442	      return;
443	    }
444	  if (g_inf_state != 0 || g_cap_pending)
445	    {
446	      return;                       /* an inference is already in flight */
447	    }
448	
449	  /* Grab the frame here (cheap, ~ms), but hand the INFERENCE to the worker.
450	   * Running embed() inline on this task wedged the SoC -- see the note on the
451	   * worker state above. The loop picks the result up when g_inf_state == 3. */
452	  cam_grab(&g_inf_frame);
453	  g_inf_mode    = 1;                /* enroll capture: embed, don't match */
454	  g_cap_pending = 1;
455	  g_inf_state   = 1;                /* -> worker */
456	  lv_label_set_text(g_sample_lbl, "capturing...");
457	}
458	
459	/* Called from the UI loop once the worker has embedded an enroll capture. */
460	static void finish_capture(void)
461	{
462	  memcpy(g_samples[g_nsamp], g_inf_emb, sizeof(g_inf_emb));
463	  frame_to_thumb565(&g_inf_frame, g_thumb565[g_nsamp]);
464	  lv_image_set_src(g_thumb[g_nsamp], &g_thumb_dsc[g_nsamp]);
465	  g_nsamp++;
466	  printf("velapaw/ui: captured sample %d/%d\n", g_nsamp, MAX_SHOTS);
467	
468	  g_cap_pending = 0;
469	  g_inf_mode    = 0;
470	  g_inf_state   = 0;                /* worker free; preview resumes */
471	  refresh_enroll();
472	}
