583	static void do_save(void)
584	{
585	  if (g_nsamp == 0)
586	    {
587	      lv_label_set_text(g_sample_lbl, "capture at least 1 sample");
588	      return;
589	    }
590	  char name[VELAPAW_NAME_MAX];
591	  const char *typed = lv_textarea_get_text(g_name_ta);
592	  if (typed && typed[0] != '\0')
593	    {
594	      strncpy(name, typed, sizeof(name) - 1);
595	      name[sizeof(name) - 1] = '\0';
596	    }
597	  else
598	    {
599	      snprintf(name, sizeof(name), "Pet %d", g_petn + 1);
600	    }
601	  int portion = (int)lv_slider_get_value(g_portion_slider);
602	  int limit   = (int)lv_slider_get_value(g_limit_slider);
603	  if (limit < portion)
604	    {
605	      limit = portion;   /* never below one serving */
606	    }
607	  velapaw_pet_id_t id = velapaw_identity_enroll(name, portion,
608	                                                UI_DEMO_COOLDOWN_S, limit,
609	                                                g_meal_min,   /* 3 meal times */
610	                                                g_samples, g_nsamp);
611	  printf("velapaw/ui: saved %s (id %d) %dg from %d samples\n",
612	         name, id, portion, g_nsamp);
613	
614	  /* Card icon: down-sample a middle capture's 64x64 thumbnail to the icon size
615	   * (nearest-neighbour) and persist it. Reuses the enroll thumbnail, which is
616	   * already rotated to display orientation. */
617	  if (id != VELAPAW_PET_UNKNOWN && g_nsamp > 0)
618	    {
619	      static uint16_t icon[VELAPAW_ICON_W * VELAPAW_ICON_H];
620	      const uint16_t *src = g_thumb565[g_nsamp / 2];   /* a middle shot */
621	      for (int y = 0; y < VELAPAW_ICON_H; y++)
622	        for (int x = 0; x < VELAPAW_ICON_W; x++)
623	          icon[y * VELAPAW_ICON_W + x] =
624	              src[(y * THUMB_H / VELAPAW_ICON_H) * THUMB_W
625	                  + (x * THUMB_W / VELAPAW_ICON_W)];
626	      velapaw_identity_set_icon(id, icon);
627	      velapaw_identity_save_icons();
628	    }
629	
630	  velapaw_identity_save();               /* persist to flash: survives reset */
631	  velapaw_store_seed(id, portion * 3);   /* baseline ~3 meals/day for trends */
632	  g_petn++;
633	  g_nsamp = 0;
634	  lv_textarea_set_text(g_name_ta, "");
635	  refresh_enroll();
636	  refresh_pets();
637	  lv_label_set_text_fmt(g_count, "enrolled pets: %d", velapaw_identity_count());
638	
639	  char msg[96];
640	  snprintf(msg, sizeof(msg),
641	           "%s enrolled. The feeder can now recognize this pet.", name);
642	  show_enroll_popup(msg);
643	}
