907	static void refresh_edit(void)
908	{
909	  if (g_edit_modal == NULL || g_edit_pet < 0)
910	    {
911	      return;
912	    }
913	
914	  char buf[64]; int n = 0;
915	  n += snprintf(buf + n, sizeof(buf) - n, LV_SYMBOL_BELL " Meals:");
916	  for (int k = 0; k < VELAPAW_MAX_MEALS && n < (int)sizeof(buf) - 12; k++)
917	    {
918	      n += snprintf(buf + n, sizeof(buf) - n,
919	                    (k == g_meal_sel) ? " [%02d:%02d]" : " %02d:%02d",
