993	/* Delete a pet, keeping every per-pet table in step.
994	 *
995	 * Pet ids ARE array indices, so velapaw_identity_delete() renumbers every pet
996	 * after the deleted one. Anything keyed by id must shift the same way or the
997	 * data ends up on the wrong animal: the feeding history (store), the meal
998	 * timeline tables here, and any id we're currently holding. */
999	static void do_delete_pet(velapaw_pet_id_t id)
1000	{
1001	  int n = velapaw_identity_count();
1002	  int p, k;
1003	
1004	  if (id < 0 || id >= n)
1005	    {
1006	      return;
1007	    }
1008	
1009	  /* shift this file's per-pet tables down over the deleted slot */
1010	  for (p = id; p < VELAPAW_MAX_PETS - 1; p++)
1011	    {
1012	      for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1013	        {
1014	          g_meal_fed_day[p][k] = g_meal_fed_day[p + 1][k];
1015	          g_meal_fed_min[p][k] = g_meal_fed_min[p + 1][k];
1016	          g_meal_fed_g[p][k]   = g_meal_fed_g[p + 1][k];
1017	        }
1018	      g_last_fed[p] = g_last_fed[p + 1];
1019	    }
1020	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1021	    {
1022	      g_meal_fed_day[VELAPAW_MAX_PETS - 1][k] = 0;   /* 0 = never fed */
1023	      g_meal_fed_min[VELAPAW_MAX_PETS - 1][k] = 0;
1024	      g_meal_fed_g[VELAPAW_MAX_PETS - 1][k]   = 0;
1025	    }
1026	  g_last_fed[VELAPAW_MAX_PETS - 1] = 0;
1027	
1028	  velapaw_store_delete(id);            /* history + BCS, shifted to match */
1029	  velapaw_identity_delete(id);         /* the pet itself + icon, renumbers rest */
1030	  velapaw_identity_save();             /* persist: stays deleted after reset */
1031	  velapaw_identity_save_icons();       /* icons were shifted too */
1032	
1033	  /* every id we were holding may now point at a different pet */
1034	  g_fed_visit = VELAPAW_PET_UNKNOWN;
1035	  g_bcs_for   = VELAPAW_PET_UNKNOWN;
1036	  g_cand      = VELAPAW_PET_UNKNOWN;
1037	  g_stable    = 0;
1038	
1039	  n = velapaw_identity_count();
1040	  if (g_trend_pet >= n) g_trend_pet = (n > 0) ? n - 1 : 0;
1041	  g_petn = n;
1042	
1043	  printf("velapaw/ui: deleted pet %d (%d left)\n", (int)id, n);
1044	}
