1514	/* True while the user is touching the screen (scrolling/pressing). We pause
1515	 * the blocking camera capture during interaction so scrolling stays smooth. */
1516	static bool ui_touch_active(void)
1517	{
1518	  lv_indev_t *indev = lv_indev_get_next(NULL);
1519	  while (indev)
1520	    {
1521	      if (lv_indev_get_state(indev) == LV_INDEV_STATE_PRESSED)
1522	        {
1523	          return true;
1524	        }
1525	      indev = lv_indev_get_next(indev);
1526	    }
1527	  return false;
1528	}
1529	
1530	/* ---- background inference worker -----------------------------------------
1531	 * Runs the ~1.3s embed()+match() OFF the UI thread so touch + LVGL stay live
1532	 * while the model runs. Single producer (UI loop) / single consumer (worker),
1533	 * coordinated by g_inf_state: 0 idle -> 1 request -> 2 busy -> 3 done -> 0.
1534	 * The UI pauses camera preview capture while state != 0 so the shared frame
1535	 * buffer the worker reads is never overwritten mid-inference.
1536	 * (State lives near the top of the file -- Capture needs it too.) */
1537	
1538	static void *recog_worker(void *arg)
1539	{
1540	  (void)arg;
1541	  for (;;)
1542	    {
1543	      if (g_inf_state != 1) { usleep(5000); continue; }
1544	      g_inf_state = 2;
1545	      g_be->embed(&g_inf_frame, g_inf_emb, VELAPAW_EMBED_DIM);
1546	      g_inf_us = g_be->last_latency_us();
1547	      if (g_inf_mode == 0)
1548	        {
1549	          velapaw_identity_match(g_inf_emb, &g_inf_m);  /* recognize only */
1550	        }
1551	      g_inf_state = 3;
1552	    }
1553	  return NULL;
1554	}
1555	
1556	void velapaw_ui_run(void)
1557	{
1558	  lv_nuttx_dsc_t info;
1559	  lv_nuttx_result_t result;
1560	
1561	  /* CRITICAL for a standalone demo: the console is a USB CDC with only a
1562	   * 193-byte TX buffer (CONFIG_CDCACM_TXBUFSIZE). If nothing is draining the
1563	   * port -- i.e. no PC attached, which is exactly the demo case -- that buffer
1564	   * fills and printf() BLOCKS, freezing the UI + camera. It bit us on the first
1565	   * feed (the feeder/store printfs). Make stdout non-blocking so printf drops
1566	   * output instead of stalling; logging still works when a host is reading. */
1567	  { int _fl = fcntl(STDOUT_FILENO, F_GETFL, 0);
1568	    if (_fl >= 0) fcntl(STDOUT_FILENO, F_SETFL, _fl | O_NONBLOCK);
1569	    _fl = fcntl(STDERR_FILENO, F_GETFL, 0);
1570	    if (_fl >= 0) fcntl(STDERR_FILENO, F_SETFL, _fl | O_NONBLOCK); }
1571	
1572	  lv_init();
1573	  lv_nuttx_dsc_init(&info);
1574	  lv_nuttx_init(&info, &result);
1575	  if (result.disp == NULL)
1576	    {
1577	      printf("velapaw/ui: LVGL display init failed\n");
1578	      return;
1579	    }
1580	  printf("velapaw/ui: LVGL ready; touch indev %s\n",
1581	         result.indev ? "ok" : "MISSING");
1582	
1583	  lv_obj_t *scr = lv_screen_active();
1584	  lv_obj_set_style_bg_color(scr, lv_color_hex(COL_BG), LV_PART_MAIN);
1585	
1586	  g_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
1587	  g_dsc.header.cf = LV_COLOR_FORMAT_RGB565;
1588	  g_dsc.header.w = VELAPAW_FRAME_W;
1589	  g_dsc.header.h = VELAPAW_FRAME_H;
1590	  g_dsc.header.stride = VELAPAW_FRAME_W * 2;
1591	  g_dsc.data = (const uint8_t *)g_img565;
1592	  g_dsc.data_size = sizeof(g_img565);
1593	
1594	  /* full-screen root */
1595	  lv_obj_t *col = lv_obj_create(scr);
1596	  lv_obj_set_size(col, SCR_W, SCR_H);
1597	  lv_obj_align(col, LV_ALIGN_CENTER, 0, 0);
1598	  lv_obj_set_style_bg_color(col, lv_color_hex(COL_BG), 0);
1599	  lv_obj_set_style_border_width(col, 0, 0);
1600	  lv_obj_set_style_pad_all(col, 0, 0);
1601	  lv_obj_set_style_radius(col, 0, 0);
1602	  lv_obj_clear_flag(col, LV_OBJ_FLAG_SCROLLABLE);
1603	
1604	  /* slim header: breadcrumb + bell */
1605	  lv_obj_t *hdr = lv_obj_create(col);
1606	  lv_obj_set_size(hdr, SCR_W, 24);
1607	  lv_obj_align(hdr, LV_ALIGN_TOP_MID, 0, 0);
1608	  lv_obj_set_style_bg_opa(hdr, LV_OPA_TRANSP, 0);
1609	  lv_obj_set_style_border_width(hdr, 0, 0);
1610	  lv_obj_set_style_pad_all(hdr, 0, 0);
1611	  lv_obj_clear_flag(hdr, LV_OBJ_FLAG_SCROLLABLE);
1612	  g_crumb = make_label(hdr, F_BODY, COL_TEXT);
1613	  lv_label_set_text(g_crumb, "VelaPaw  -  Enroll");
1614	  lv_obj_align(g_crumb, LV_ALIGN_LEFT_MID, 8, 0);
1615	  g_bell = make_label(hdr, F_HEAD, COL_DIM);
1616	  lv_label_set_text(g_bell, LV_SYMBOL_BELL);
1617	  lv_obj_align(g_bell, LV_ALIGN_RIGHT_MID, -8, 0);
1618	  lv_obj_add_flag(g_bell, LV_OBJ_FLAG_CLICKABLE);
1619	  lv_obj_set_ext_click_area(g_bell, 16);   /* larger tap target */
1620	  lv_obj_add_event_cb(g_bell, bell_cb, LV_EVENT_CLICKED, NULL);
1621	
1622	  /* tabview fills the rest */
1623	  g_tv = lv_tabview_create(col);
1624	  lv_tabview_set_tab_bar_position(g_tv, LV_DIR_TOP);
1625	  lv_tabview_set_tab_bar_size(g_tv, 30);
1626	  lv_obj_set_size(g_tv, SCR_W, SCR_H - 24);
1627	  lv_obj_align(g_tv, LV_ALIGN_TOP_MID, 0, 24);
1628	  lv_obj_set_style_bg_color(g_tv, lv_color_hex(COL_BG), 0);
1629	  lv_obj_set_style_bg_color(lv_tabview_get_content(g_tv), lv_color_hex(COL_BG), 0);
1630	
1631	  lv_obj_t *t_en = lv_tabview_add_tab(g_tv, "Enroll");
1632	  lv_obj_t *t_rc = lv_tabview_add_tab(g_tv, "Recognize");
1633	  lv_obj_t *t_mp = lv_tabview_add_tab(g_tv, "My Pets");
1634	  lv_obj_t *t_tr = lv_tabview_add_tab(g_tv, "Trends");
1635	  lv_obj_set_style_bg_color(t_en, lv_color_hex(COL_BG), 0);
1636	  lv_obj_set_style_bg_color(t_rc, lv_color_hex(COL_BG), 0);
1637	  lv_obj_set_style_bg_color(t_mp, lv_color_hex(COL_BG), 0);
1638	  lv_obj_set_style_bg_color(t_tr, lv_color_hex(COL_BG), 0);
1639	
1640	  /* No momentum/elastic scroll: on the slow bit-bang panel the post-release
1641	   * glide/bounce animation is many slow full repaints -> judder. Direct
1642	   * finger-tracked scroll stops the instant you lift = crisper. */
1643	  lv_obj_clear_flag(t_en, LV_OBJ_FLAG_SCROLL_MOMENTUM | LV_OBJ_FLAG_SCROLL_ELASTIC);
1644	  lv_obj_clear_flag(t_rc, LV_OBJ_FLAG_SCROLL_MOMENTUM | LV_OBJ_FLAG_SCROLL_ELASTIC);
1645	  lv_obj_clear_flag(t_mp, LV_OBJ_FLAG_SCROLL_MOMENTUM | LV_OBJ_FLAG_SCROLL_ELASTIC);
1646	  lv_obj_clear_flag(t_tr, LV_OBJ_FLAG_SCROLL_MOMENTUM | LV_OBJ_FLAG_SCROLL_ELASTIC);
1647	
1648	  /* ---- init pipeline (before building tabs that read state) ---- */
1649	  g_be = velapaw_infer_active();
1650	  velapaw_camera_open();
1651	  printf("velapaw: '%s' backend init...\n", g_be->name);
1652	  { int _ir = g_be->init();
1653	    printf("velapaw: init ret=%d arena=%lu KB\n", _ir,
1654	           (unsigned long)(g_be->arena_bytes() / 1024)); }
1655	  /* spin up the background inference worker (keeps Invoke off the UI thread) */
1656	  { pthread_t _wt; pthread_attr_t _wa; pthread_attr_init(&_wa);
1657	    pthread_attr_setstacksize(&_wa, 32768);
1658	    if (pthread_create(&_wt, &_wa, recog_worker, NULL) == 0)
1659	      pthread_detach(_wt);
1660	    pthread_attr_destroy(&_wa);
1661	    printf("velapaw: recog worker started\n"); }
1662	  velapaw_identity_init();
1663	  velapaw_store_init();
1664	  velapaw_feeder_init();
1665	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
1666	    {
1667	      g_last_fed[i] = -100000;
1668	      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
1669	        {
1670	          g_meal_fed_day[i][k] = -1;   /* no scheduled meal eaten yet */
1671	        }
1672	    }
1673	  /* Time comes from the on-board PCF85063 RTC (synced in board_lcd_initialize),
1674	   * so it persists across resets. That chip only stores years 2000-2099 -- its
1675	   * year register is an offset from 2000 -- so the clock MUST live in that
1676	   * range or the register wraps to garbage. If what we got back is implausible
1677	   * (never set, or a pre-2000 epoch), seed a real date; the user then adjusts
1678	   * the time on Enroll and it is written straight back into the chip. */
1679	  { struct timespec _ts;
1680	    clock_gettime(CLOCK_REALTIME, &_ts);
1681	    if (_ts.tv_sec < 1500000000L)                  /* pre-2017 => not real */
1682	      {
1683	        _ts.tv_sec  = 1783900800L + 7 * 3600 + 55 * 60;  /* 2026-07-13 07:55 */
1684	        _ts.tv_nsec = 0;
1685	        clock_settime(CLOCK_REALTIME, &_ts);
1686	        board_rtc_settime(_ts.tv_sec);
1687	      } }
1688	  g_view = 0;
1689	  velapaw_camera_mock_set_scene(g_view);
1690	
1691	  build_enroll(t_en);
1692	  build_recognize(t_rc);
1693	  build_pets(t_mp);
1694	  build_trends(t_tr);
1695	  build_edit_modal();      /* hidden until a pet's "Edit schedule" is tapped */
1696	
1697	  /* keyboard floats above everything */
1698	  g_kb = lv_keyboard_create(lv_layer_top());
1699	  lv_keyboard_set_textarea(g_kb, g_name_ta);
1700	  lv_obj_add_flag(g_kb, LV_OBJ_FLAG_HIDDEN);
1701	  lv_obj_add_event_cb(g_kb, kb_cb, LV_EVENT_ALL, NULL);
1702	
1703	  refresh_enroll();
1704	  lv_label_set_text_fmt(g_count, "enrolled pets: %d", velapaw_identity_count());
1705	  lv_label_set_text_fmt(g_metrics, "backend %s   arena %lu KB", g_be->name,
1706	                        (unsigned long)g_be->arena_bytes() / 1024);
1707	
1708	  long last_recog = 0;
1709	  long last_frame = 0;
1710	  uint32_t last_tab = 99;
1711	  g_last_touch = mono_ms();     /* else Enroll starts out "idle" and paused */
1712	  struct velapaw_frame frame;
1713	  cam_grab(&frame);
1714	  show_frame(&frame);
1715	
1716	  while (1)
1717	    {
1718	      lv_timer_handler();
1719	
1720	      uint32_t tab = lv_tabview_get_tab_active(g_tv);
1721	      static const char *tabnm  = "Enroll";
1722	      static int last_clock_min = -1;
1723	      /* header shows the wall clock; repaint when the minute (or tab) changes */
1724	      { int cm = wall_min();
1725	        if (cm != last_clock_min)
1726	          {
1727	            last_clock_min = cm;
1728	            lv_label_set_text_fmt(g_crumb, "VelaPaw %02d:%02d  -  %s",
1729	                                  cm / 60, cm % 60, tabnm);
1730	          } }
1731	      if (tab != last_tab)
1732	        {
1733	          last_tab = tab;
1734	          const char *nm = (tab == 0) ? "Enroll" :
1735	                           (tab == 1) ? "Recognize" :
1736	                           (tab == 2) ? "My Pets" : "Trends";
1737	          tabnm = nm;
1738	          last_clock_min = -1;   /* force the header to repaint with the new tab */
1739	          if (tab == 2)
1740	            {
1741	              refresh_pets();
1742	            }
1743	          else if (tab == 3)
1744	            {
1745	              refresh_trends();
1746	            }
1747	        }
1748	
1749	      ui_event_t ev = g_evt;
1750	      g_evt = EV_NONE;
1751	      if (ev == EV_VIEW)
1752	        {
