static int g_lang = VP_LANG_EN;

const char *velapaw_tr(int id)
{
  if (id < 0 || id >= S_COUNT)
    {
      return "";
    }
  const char *s = g_strtab[id][g_lang];
  if (s == NULL)                       /* missing translation -> fall back to EN */
    {
      s = g_strtab[id][VP_LANG_EN];
    }
  return s ? s : "";
}

int velapaw_lang_get(void)
{
  return g_lang;
}

/* ---- persistence ----------------------------------------------------------
 * One tiny magic-tagged cell in SPI flash, just past the pet-icon area that
 * identity.c owns (pets @0x800000, icons @0x810000+32K -> 0x818000 is free).
 * Same spi_flash hooks identity uses; a missing/failed hook is non-fatal. */
extern int spi_flash_read(uint32_t src, void *dst, uint32_t size);
extern int spi_flash_write(uint32_t dst, const void *src, uint32_t size);

#define LANG_FLASH_OFF  0x818000u
#define LANG_MAGIC      0x474E414Cu    /* "LANG" */

struct lang_cell
{
  uint32_t magic;
  uint32_t lang;
};

void velapaw_lang_set(int lang)
{
  if (lang < 0 || lang >= VP_LANG_N || lang == g_lang)
    {
      return;
    }
  g_lang = lang;
  struct lang_cell c = { LANG_MAGIC, (uint32_t)lang };
  spi_flash_write(LANG_FLASH_OFF, &c, sizeof(c));   /* best effort */
}

void velapaw_lang_load(void)
{
  struct lang_cell c;
  if (spi_flash_read(LANG_FLASH_OFF, &c, sizeof(c)) == 0 &&
      c.magic == LANG_MAGIC && c.lang < VP_LANG_N)
    {
      g_lang = (int)c.lang;
    }
}

/* ---- fonts ----------------------------------------------------------------
 * THE seam. Montserrat has no CJK glyphs, so today this always returns the
 * Latin fonts (Chinese would render blank). Build CONFIG_VELAPAW_FONT_CJK=y
 * with a generated CJK font linked (ui/README_I18N.md) and it returns that
 * instead -- every label switches to it automatically. The CJK font carries
 * Latin too, so it is used for both languages once present. */
const lv_font_t *velapaw_font(int level)
{
#ifdef CONFIG_VELAPAW_FONT_CJK
  extern const lv_font_t velapaw_font_cjk_20;
  extern const lv_font_t velapaw_font_cjk_16;
  extern const lv_font_t velapaw_font_cjk_14;
  switch (level)
    {
      case VP_FONT_TITLE: return &velapaw_font_cjk_20;
      case VP_FONT_HEAD:  return &velapaw_font_cjk_16;
      default:            return &velapaw_font_cjk_14;
    }
#else
  switch (level)
    {
      case VP_FONT_TITLE: return &lv_font_montserrat_20;
      case VP_FONT_HEAD:  return &lv_font_montserrat_16;
      default:            return &lv_font_montserrat_14;
    }
#endif
}

