input.old_string:
/* ---- persistence ----------------------------------------------------------
 * One tiny magic-tagged cell in SPI flash, just past the pet-icon area that
 * identity.c owns (pets @0x800000, icons @0x810000+32K -> 0x818000 is free).
 * Same spi_flash hooks identity uses; a missing/failed hook is non-fatal. */
extern int spi_flash_read(uint32_t src, void *dst, uint32_t size);
extern int spi_flash_write(uint32_t dst, const void *src, uint32_t size);

#define LANG_FLASH_OFF  0x818000u
#define LANG_MAGIC      0x474E414Cu    /* "LANG" */

struct lang_cell
{
  uint32_t magic;
  uint32_t lang;
};

void velapaw_lang_set(int lang)
{
  if (lang < 0 || lang >= VP_LANG_N || lang == g_lang)
    {
      return;
    }
  g_lang = lang;
  struct lang_cell c = { LANG_MAGIC, (uint32_t)lang };
  spi_flash_write(LANG_FLASH_OFF, &c, sizeof(c));   /* best effort */
}

void velapaw_lang_load(void)
{
  struct lang_cell c;
  if (spi_flash_read(LANG_FLASH_OFF, &c, sizeof(c)) == 0 &&
      c.magic == LANG_MAGIC && c.lang < VP_LANG_N)
    {
      g_lang = (int)c.lang;
    }
}

input.new_string:
/* ---- persistence: intentionally RAM-only ----------------------------------
 * An earlier version stored a magic-tagged cell at flash 0x818000 (just past
 * identity's icon area). That raw spi_flash access WEDGED the SoC: a gray screen
 * at boot (the read) and a hard hang the instant you toggled language (the
 * write). 0x818000 is outside the range this board's spi_flash path handles
 * safely -- identity only ever touches 0x800000 (pets) and 0x810000 (icons).
 *
 * So language now lives only in RAM: the toggle works within a session and
 * resets to English on reboot -- fine for a demo. To persist it later, route it
 * through identity's proven flash helper (an in-range, erase-managed slot), not
 * a raw offset guessed to be "free". */

void velapaw_lang_set(int lang)
{
  if (lang < 0 || lang >= VP_LANG_N)
    {
      return;
    }
  g_lang = lang;
}

void velapaw_lang_load(void)
{
  /* no-op -- RAM-only (see note above) */
}

